create or replace function public.business_manage_qr(p_business_id uuid,p_qr_id uuid,p_location_id uuid,p_action text,p_label text default null,p_active boolean default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v jsonb; begin if not exists(select 1 from business_members where business_id=p_business_id and user_id=auth.uid() and lower(role) in('owner','admin')) and not exists(select 1 from profiles where id=auth.uid() and is_admin=true) then raise exception 'Admin authorization required'; end if; if p_action='create' then insert into qr_codes(location_id,label,active) select p_location_id,coalesce(p_label,'Business QR'),coalesce(p_active,true) where exists(select 1 from locations where id=p_location_id and business_id=p_business_id) returning to_jsonb(qr_codes.*) into v; elsif p_action='update' then update qr_codes q set label=coalesce(p_label,q.label),active=coalesce(p_active,q.active) where q.id=p_qr_id and exists(select 1 from locations l where l.id=q.location_id and l.business_id=p_business_id) returning to_jsonb(q.*) into v; elsif p_action='activate' then update qr_codes q set active=true where q.id=p_qr_id and exists(select 1 from locations l where l.id=q.location_id and l.business_id=p_business_id) returning to_jsonb(q.*) into v; elsif p_action='deactivate' then update qr_codes q set active=false where q.id=p_qr_id and exists(select 1 from locations l where l.id=q.location_id and l.business_id=p_business_id) returning to_jsonb(q.*) into v; else raise exception 'Unsupported QR action'; end if; return v; end; $$;
create or replace function public.business_delete_media(p_business_id uuid,p_media_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v jsonb; begin if not exists(select 1 from business_members where business_id=p_business_id and user_id=auth.uid() and lower(role) in('owner','admin')) and not exists(select 1 from profiles where id=auth.uid() and is_admin=true) then raise exception 'Admin authorization required'; end if; delete from location_photos p using locations l where p.id=p_media_id and l.id=p.location_id and l.business_id=p_business_id returning to_jsonb(p.*) into v; return v; end; $$;
